from pathlib import Path

root = Path('.')

# MainActivity: make the setting apply to the whole app theme and root background.
p = root / 'app/src/main/java/com/wavelength/music/MainActivity.kt'
s = p.read_text()
s = s.replace('import androidx.compose.ui.graphics.Color\n', 'import androidx.compose.ui.graphics.Brush\nimport androidx.compose.ui.graphics.Color\n')
s = s.replace('''            WavelengthTheme(\n                theme = settings.theme,\n                customLiquidAccent = Color(settings.customAccentArgb)\n            ) {''', '''            WavelengthTheme(\n                theme = settings.theme,\n                customLiquidAccent = Color(settings.customAccentArgb),\n                glassmorphismEnabled = settings.glassmorphismNowPlaying\n            ) {''')
s = s.replace('''                    Box(modifier = Modifier.fillMaxWidth().weight(1f).background(Color.Black)) {\n                        WavelengthNavHost()\n                    }''', '''                    val appSurface = if (settings.glassmorphismNowPlaying) {\n                        Modifier.background(\n                            Brush.verticalGradient(\n                                listOf(\n                                    Color(settings.customAccentArgb).copy(alpha = 0.24f),\n                                    Color(0xFF0A1628),\n                                    Color(0xFF111827)\n                                )\n                            )\n                        )\n                    } else {\n                        Modifier.background(Color.Black)\n                    }\n                    Box(modifier = Modifier.fillMaxWidth().weight(1f).then(appSurface)) {\n                        WavelengthNavHost()\n                    }''')
p.write_text(s)

# Theme: translucent global Material surfaces when glass mode is enabled.
p = root / 'app/src/main/java/com/wavelength/music/ui/theme/Theme.kt'
s = p.read_text()
s = s.replace('''fun WavelengthTheme(\n    theme: AppTheme = AppTheme.CLASSIC,\n    customLiquidAccent: Color? = null,\n    content: @Composable () -> Unit\n) {\n    MaterialTheme(\n        colorScheme = schemeFor(theme, customLiquidAccent),''', '''fun WavelengthTheme(\n    theme: AppTheme = AppTheme.CLASSIC,\n    customLiquidAccent: Color? = null,\n    glassmorphismEnabled: Boolean = false,\n    content: @Composable () -> Unit\n) {\n    val baseScheme = schemeFor(theme, customLiquidAccent)\n    val appScheme = if (glassmorphismEnabled) {\n        baseScheme.copy(\n            background = Color.Transparent,\n            surface = Color.White.copy(alpha = 0.10f),\n            surfaceVariant = Color.White.copy(alpha = 0.16f),\n            surfaceContainer = Color.White.copy(alpha = 0.09f),\n            surfaceContainerLow = Color.White.copy(alpha = 0.07f),\n            surfaceContainerHigh = Color.White.copy(alpha = 0.14f),\n            outline = Color.White.copy(alpha = 0.34f),\n            outlineVariant = Color.White.copy(alpha = 0.20f),\n            onBackground = Color.White,\n            onSurface = Color.White,\n            onSurfaceVariant = Color.White.copy(alpha = 0.78f)\n        )\n    } else {\n        baseScheme\n    }\n    MaterialTheme(\n        colorScheme = appScheme,''')
p.write_text(s)

# Settings: the toggle now explicitly controls the entire app.
p = root / 'app/src/main/java/com/wavelength/music/ui/settings/SettingsScreen.kt'
s = p.read_text()
s = s.replace('SettingsSection(title = "Now Playing Style")', 'SettingsSection(title = "Glassmorphism Theme")')
s = s.replace('Text("Glassmorphism Now Playing")', 'Text("Full App Glassmorphism")')
s = s.replace('''                                    "On • frosted glass with a blurred album-art backdrop"\n                                } else {\n                                    "Off • use the standard Now Playing layout"''', '''                                    "On • frosted liquid-glass styling across the entire app"\n                                } else {\n                                    "Off • use the standard AzMusic interface"''')
s = s.replace('''                        text = "Transforms the entire Now Playing screen into a translucent frosted-glass interface while keeping playback controls, lyrics, volume and Up Next fully usable.",''', '''                        text = "Applies the translucent frosted-glass theme to Home, Search, Library, Settings, dialogs, cards and Now Playing. The player also uses the reference-style curved queue, seek arc and connected transport control.",''')
p.write_text(s)

# Now Playing: stronger seek arc, scrollable arced Up Next labels, and one continuous Saturn transport outline.
p = root / 'app/src/main/java/com/wavelength/music/ui/nowplaying/NowPlayingScreen.kt'
s = p.read_text()
for old, new in [
    ('import androidx.compose.foundation.layout.Arrangement\n', 'import androidx.compose.foundation.layout.Arrangement\nimport androidx.compose.foundation.layout.PaddingValues\n'),
    ('import androidx.compose.foundation.layout.fillMaxSize\n', 'import androidx.compose.foundation.layout.fillMaxHeight\nimport androidx.compose.foundation.layout.fillMaxSize\n'),
    ('import androidx.compose.foundation.layout.height\n', 'import androidx.compose.foundation.layout.height\nimport androidx.compose.foundation.layout.offset\n'),
    ('import androidx.compose.foundation.layout.size\n', 'import androidx.compose.foundation.layout.size\nimport androidx.compose.foundation.layout.width\n'),
    ('import androidx.compose.foundation.lazy.LazyColumn\n', 'import androidx.compose.foundation.lazy.LazyColumn\nimport androidx.compose.foundation.lazy.LazyRow\n'),
    ('import androidx.compose.foundation.shape.CircleShape\n', 'import androidx.compose.foundation.shape.CircleShape\nimport androidx.compose.foundation.shape.GenericShape\n'),
]:
    s = s.replace(old, new)

s = s.replace('''            if (glassmorphismNowPlaying) {\n                Box(modifier = Modifier.weight(1f))\n            }''', '''            if (glassmorphismNowPlaying) {\n                val glassUpcoming = state.queue.drop(state.currentIndex + 1).take(12)\n                Box(\n                    modifier = Modifier\n                        .fillMaxWidth()\n                        .weight(1f),\n                    contentAlignment = Alignment.BottomCenter\n                ) {\n                    if (glassUpcoming.isNotEmpty()) {\n                        LazyRow(\n                            modifier = Modifier\n                                .fillMaxWidth()\n                                .height(118.dp),\n                            contentPadding = PaddingValues(horizontal = 96.dp),\n                            horizontalArrangement = Arrangement.spacedBy(14.dp),\n                            verticalAlignment = Alignment.CenterVertically\n                        ) {\n                            itemsIndexed(glassUpcoming, key = { _, entry -> entry.instanceId }) { index, entry ->\n                                val arcOffset = when (index % 5) {\n                                    0, 4 -> 28.dp\n                                    1, 3 -> 12.dp\n                                    else -> 0.dp\n                                }\n                                Column(\n                                    modifier = Modifier\n                                        .width(92.dp)\n                                        .offset(y = arcOffset)\n                                        .clip(RoundedCornerShape(18.dp))\n                                        .background(Color.White.copy(alpha = 0.08f))\n                                        .border(1.dp, Color.White.copy(alpha = 0.22f), RoundedCornerShape(18.dp))\n                                        .clickable { viewModel.playQueueItem(state.currentIndex + 1 + index) }\n                                        .padding(horizontal = 8.dp, vertical = 10.dp),\n                                    horizontalAlignment = Alignment.CenterHorizontally\n                                ) {\n                                    Text(\n                                        text = "%02d".format(index + 1),\n                                        style = MaterialTheme.typography.labelSmall,\n                                        color = Color.White.copy(alpha = 0.70f)\n                                    )\n                                    Text(\n                                        text = entry.track.name,\n                                        style = MaterialTheme.typography.labelMedium,\n                                        color = Color.White.copy(alpha = 0.92f),\n                                        maxLines = 2,\n                                        overflow = TextOverflow.Ellipsis,\n                                        textAlign = TextAlign.Center\n                                    )\n                                }\n                            }\n                        }\n                    }\n                }\n            }''')

# Deepen and widen the glass seek arc.
s = s.replace('''.height(112.dp)\n                            .padding(horizontal = 10.dp)''', '''.height(132.dp)\n                            .padding(horizontal = 2.dp)''')
s = s.replace('''                            val stroke = 3.0.dp.toPx()\n                            val arcLeft = 6.dp.toPx()\n                            val arcRight = size.width - 6.dp.toPx()\n                            val arcWidth = arcRight - arcLeft\n                            val arcHeight = 138.dp.toPx()\n                            val top = 8.dp.toPx()\n                            val arcSize = Size(arcWidth, arcHeight)\n                            val startAngle = 198f\n                            val sweepAngle = 144f''', '''                            val stroke = 3.4.dp.toPx()\n                            val arcLeft = 0.dp.toPx()\n                            val arcRight = size.width\n                            val arcWidth = arcRight - arcLeft\n                            val arcHeight = 214.dp.toPx()\n                            val top = 10.dp.toPx()\n                            val arcSize = Size(arcWidth, arcHeight)\n                            val startAngle = 202f\n                            val sweepAngle = 136f''')

start_marker = '                // Organic three-part liquid transport: left and right lobes curve into the raised\n'
end_marker = '            } else {\n                Column(modifier = Modifier.fillMaxWidth().padding(top = 16.dp)) {'
start = s.index(start_marker)
end = s.index(end_marker, start)
new_transport = '''                // One continuous reference-style Saturn control. The outer glass border is a\n                // single organic silhouette shared by Previous, Play/Pause and Next.\n                val saturnTransportShape = remember {\n                    GenericShape { size, _ ->\n                        val w = size.width\n                        val h = size.height\n                        moveTo(0f, h * 0.50f)\n                        cubicTo(0f, h * 0.34f, w * 0.04f, h * 0.28f, w * 0.10f, h * 0.28f)\n                        lineTo(w * 0.28f, h * 0.28f)\n                        cubicTo(w * 0.34f, h * 0.28f, w * 0.34f, h * 0.08f, w * 0.42f, h * 0.03f)\n                        cubicTo(w * 0.47f, 0f, w * 0.53f, 0f, w * 0.58f, h * 0.03f)\n                        cubicTo(w * 0.66f, h * 0.08f, w * 0.66f, h * 0.28f, w * 0.72f, h * 0.28f)\n                        lineTo(w * 0.90f, h * 0.28f)\n                        cubicTo(w * 0.96f, h * 0.28f, w, h * 0.34f, w, h * 0.50f)\n                        cubicTo(w, h * 0.66f, w * 0.96f, h * 0.72f, w * 0.90f, h * 0.72f)\n                        lineTo(w * 0.72f, h * 0.72f)\n                        cubicTo(w * 0.66f, h * 0.72f, w * 0.66f, h * 0.92f, w * 0.58f, h * 0.97f)\n                        cubicTo(w * 0.53f, h, w * 0.47f, h, w * 0.42f, h * 0.97f)\n                        cubicTo(w * 0.34f, h * 0.92f, w * 0.34f, h * 0.72f, w * 0.28f, h * 0.72f)\n                        lineTo(w * 0.10f, h * 0.72f)\n                        cubicTo(w * 0.04f, h * 0.72f, 0f, h * 0.66f, 0f, h * 0.50f)\n                        close()\n                    }\n                }\n                Box(\n                    modifier = Modifier\n                        .fillMaxWidth()\n                        .height(132.dp)\n                        .padding(horizontal = 18.dp),\n                    contentAlignment = Alignment.Center\n                ) {\n                    Box(\n                        modifier = Modifier\n                            .fillMaxWidth()\n                            .height(116.dp)\n                            .clip(saturnTransportShape)\n                            .background(Color.White.copy(alpha = 0.13f))\n                            .border(1.6.dp, Color.White.copy(alpha = 0.68f), saturnTransportShape)\n                    ) {\n                        Row(modifier = Modifier.fillMaxSize(), verticalAlignment = Alignment.CenterVertically) {\n                            Box(\n                                modifier = Modifier\n                                    .weight(1f)\n                                    .fillMaxHeight()\n                                    .clickable(onClick = viewModel::skipPrevious),\n                                contentAlignment = Alignment.Center\n                            ) {\n                                Icon(\n                                    Icons.Filled.SkipPrevious,\n                                    contentDescription = "Previous",\n                                    tint = Color.White,\n                                    modifier = Modifier.size(30.dp)\n                                )\n                            }\n                            Box(modifier = Modifier.width(112.dp).fillMaxHeight())\n                            Box(\n                                modifier = Modifier\n                                    .weight(1f)\n                                    .fillMaxHeight()\n                                    .clickable(onClick = viewModel::skipNext),\n                                contentAlignment = Alignment.Center\n                            ) {\n                                Icon(\n                                    Icons.Filled.SkipNext,\n                                    contentDescription = "Next",\n                                    tint = Color.White,\n                                    modifier = Modifier.size(30.dp)\n                                )\n                            }\n                        }\n                    }\n                    Box(\n                        modifier = Modifier\n                            .size(108.dp)\n                            .clip(CircleShape)\n                            .background(Color.White.copy(alpha = 0.10f))\n                    )\n                    Box(\n                        modifier = Modifier\n                            .size(88.dp)\n                            .clip(CircleShape)\n                            .background(Color.White.copy(alpha = 0.98f))\n                            .clickable(enabled = !state.isBuffering, onClick = viewModel::playPause),\n                        contentAlignment = Alignment.Center\n                    ) {\n                        if (state.isBuffering) {\n                            CircularProgressIndicator(\n                                strokeWidth = 3.dp,\n                                color = Color.Black,\n                                modifier = Modifier.size(30.dp)\n                            )\n                        } else {\n                            Icon(\n                                imageVector = if (state.isPlaying) Icons.Filled.Pause else Icons.Filled.PlayArrow,\n                                contentDescription = "Play/Pause",\n                                tint = Color.Black,\n                                modifier = Modifier.size(42.dp)\n                            )\n                        }\n                    }\n                }\n'''
s = s[:start] + new_transport + s[end:]
p.write_text(s)

# About: document this change as the newest update and update Personalization wording.
p = root / 'app/src/main/java/com/wavelength/music/ui/settings/AboutSheet.kt'
s = p.read_text()
s = s.replace('private val latestUpdates = listOf(\n', 'private val latestUpdates = listOf(\n    "Glassmorphism is now a full-app theme with a continuous Saturn transport border, deeper curved seek arc, and scrollable arced Up Next cards",\n', 1)
s = s.replace('"Optional Glassmorphism Now Playing interface with frosted album-art backdrop",', '"Optional full-app Glassmorphism theme with frosted translucent surfaces and reference-style playback controls",')
p.write_text(s)
